        // Check the error code
        if (errno == ENOENT) {
            printf("The file was not found.\n");
        } else {
            printf("An unexpected error occurred.\n");
        }
    } else {
        // File was found and opened successfully
        fclose(file);
    }
    return 0;
}
```

In this example, `open_file` returns a `FILE*` pointer if the file is found, or `-1` if the file is not found. The `errno` is set to `ENOENT` in the case of a file not found, and the calling function checks the value of `errno` to determine if an error occurred.

